host:
return {
  inject: ['systemPrompt'],
  apply(ctx) {
    ctx.effect(() => ctx.systemPrompt.section({
      name: 'at-mention-convention',
      order: 200,
      text: [
        '## @ 提及约定',
        '用户消息中的 @ 提及表示引用当前可用的技能或插件：',
        '- @<skill>（例如 @openspec-propose、@cordis-plugin-development）：要求执行对应技能——用 skill 工具加载名为 <skill> 的技能并严格按其说明执行；@ 之后紧跟的用户文本是该技能的输入。',
        '- @<pluginId>（例如 @ops-1、@agent-teams，指已安装的 Cordis 插件，动态或组合装载）：用户指的是该插件；动态插件用 cordis_inspect_self 等工具查看/操作；组合插件按其用途执行（如 @agent-teams 即用 AgentTeams 团队工作流）；若未激活，明确说明。',
        '- 若引用的技能或插件在当前会话不可用，明确告知用户，不要臆造。',
      ].join('\n'),
    }), 'openspec: at-mention prompt section')
  },
}

client:
return {
  inject: ['inputTriggers', 'connection', 'sessions'],
  apply(ctx) {
    // Category tree: one @ source per category renders as a titled menu group.
    const CATEGORIES = [
      { name: 'openspec', order: 0, match: (name) => name.startsWith('openspec-') },
      { name: 'design', order: 1, match: (name) => name === 'hallmark' || name.startsWith('design-') || name.startsWith('hallmark-') },
      { name: 'dev', order: 2, match: (name) => name.startsWith('cordis-') || name.startsWith('editing-') },
      { name: 'marcus', order: 3, match: (name) => name.startsWith('marcus-') },
      { name: 'other', order: 4, match: (name) => !name.startsWith('openspec-') && !name.startsWith('design-') && !name.startsWith('hallmark-') && name !== 'hallmark' && !name.startsWith('marcus-') && !name.startsWith('cordis-') && !name.startsWith('editing-') },
    ]
    const PLUGINS = [
      { name: 'agent-teams', description: 'AgentTeams 多智能体团队插件（用 AgentTeams 驱动）' },
    ]
    const FALLBACK = [
      'openspec-explore', 'openspec-propose', 'openspec-apply-change',
      'openspec-update-change', 'openspec-sync-specs', 'openspec-archive-change',
    ]
    const fetches = new Map()
    const listeners = new Map()
    const notify = (sessionId) => {
      for (const fn of [...(listeners.get(sessionId) ?? [])]) {
        try { fn() } catch (error) { console.error('[mention] lexicon listener failed', error) }
      }
    }
    const fetchCatalog = (sessionId) => {
      if (ctx.sessions?.subagentAddress?.(sessionId) !== undefined) return Promise.resolve([])
      const existing = fetches.get(sessionId)
      if (existing !== undefined) return existing.promise
      const abort = new AbortController()
      const promise = (async () => {
        const api = ctx.connection?.api
        if (api?.skills?.list === undefined) return FALLBACK.map((name) => ({ name, description: undefined, modelInvocable: true }))
        const { result } = await api.skills.list({ sessionId }, abort.signal)
        if (!result.ok) throw new Error(`skill.list failed: ${result.error.code}: ${result.error.message}`)
        return result.value.skills
      })()
      const entry = { promise, abort }
      fetches.set(sessionId, entry)
      promise.then((skills) => {
        entry.settled = skills
        notify(sessionId)
      }, () => {
        if (fetches.get(sessionId) === entry) fetches.delete(sessionId)
      })
      return promise
    }
    const clearAll = () => {
      for (const key of [...fetches.keys()]) {
        const entry = fetches.get(key)
        if (entry === undefined) continue
        fetches.delete(key)
        entry.abort.abort()
        notify(key)
      }
    }
    const disposers = []
    for (const cat of CATEGORIES) {
      const source = {
        trigger: '@',
        name: cat.name,
        order: cat.order,
        async candidates(session, { query, signal }) {
          const skills = await fetchCatalog(session.sessionId)
          if (signal.aborted) return []
          const q = query.toLowerCase()
          return skills
            .filter((skill) => typeof skill.name === 'string' && cat.match(skill.name) && skill.name.toLowerCase().startsWith(q))
            .map((skill) => ({
              name: skill.name,
              description: skill.modelInvocable === false ? `仅用户 · ${skill.description ?? ''}` : (skill.description ?? cat.name),
            }))
        },
        warm(session) {
          fetchCatalog(session.sessionId).catch(() => {})
        },
        lexicon(session) {
          return (fetches.get(session.sessionId)?.settled ?? [])
            .filter((skill) => typeof skill.name === 'string' && cat.match(skill.name))
            .map((skill) => skill.name)
        },
        subscribeLexicon(session, listener) {
          const key = session.sessionId
          const set = listeners.get(key) ?? new Set()
          set.add(listener)
          listeners.set(key, set)
          return () => {
            set.delete(listener)
            if (set.size === 0) listeners.delete(key)
          }
        },
        onPick({ candidate }) {
          return { text: `@${candidate.name} ` }
        },
      }
      disposers.push(ctx.inputTriggers.registerSource(source))
    }
    const pluginsSource = {
      trigger: '@',
      name: 'plugins',
      order: 5,
      async candidates(session, { query }) {
        const q = query.toLowerCase()
        return PLUGINS.filter((p) => p.name.toLowerCase().startsWith(q))
      },
      lexicon() { return PLUGINS.map((p) => p.name) },
      onPick({ candidate }) { return { text: '@' + candidate.name + ' ' } },
    }
    disposers.push(ctx.inputTriggers.registerSource(pluginsSource))
    ctx.effect(() => () => {
      for (const off of disposers) off()
    }, 'mention: @ category sources')
    ctx.on('connection/reset', clearAll)
  },
}
